from collections import deque

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    exams = []
    index = 2
    for _ in range(m):
        s_i = int(data[index])
        d_i = int(data[index + 1])
        c_i = int(data[index + 2])
        exams.append((s_i, d_i, c_i))
        index += 3

    # Create a graph where each exam is a node
    graph = [[] for _ in range(m)]

    # Add edges based on feasible preparation days
    for i in range(m):
        s_i, d_i, c_i = exams[i]
        for j in range(m):
            if i != j:
                s_j, d_j, c_j = exams[j]
                if d_i <= s_j:
                    if d_i + c_i <= s_j:
                        graph[i].append(j)
                elif d_j <= s_i:
                    if d_j + c_j <= s_i:
                        graph[j].append(i)

    # BFS to find a valid schedule
    queue = deque([(0, [0] * n)])
    visited = set()
    visited.add(0)

    while queue:
        current_exam, schedule = queue.popleft()

        if current_exam == m:
            for i in range(n):
                if schedule[i] == 0:
                    schedule[i] = m + 1
            return ' '.join(map(str, schedule))

        s_i, d_i, c_i = exams[current_exam]

        # Try to prepare for the current exam
        for day in range(s_i, d_i):
            if schedule[day - 1] == 0:
                new_schedule = schedule[:]
                new_schedule[day - 1] = current_exam + 1
                state = tuple(new_schedule)
                if state not in visited:
                    visited.add(state)
                    queue.append((current_exam + 1, new_schedule))

        # Try to take the current exam
        if schedule[d_i - 1] == 0:
            new_schedule = schedule[:]
            new_schedule[d_i - 1] = m + 1
            state = tuple(new_schedule)
            if state not in visited:
                visited.add(state)
                queue.append((current_exam + 1, new_schedule))

    return '-1'

