def find_schedule(n, m, exams):
    def backtrack(day, schedule):
        if day == n + 1:
            return True
        if schedule[day - 1] != 0:
            return backtrack(day + 1, schedule)

        for i in range(m):
            s_i, d_i, c_i = exams[i]
            if d_i == day:
                schedule[day - 1] = m + 1
                if backtrack(day + 1, schedule):
                    return True
                schedule[day - 1] = 0
            elif s_i <= day < d_i and c_i > 0:
                schedule[day - 1] = i + 1
                exams[i] = (s_i, d_i, c_i - 1)
                if backtrack(day + 1, schedule):
                    return True
                schedule[day - 1] = 0
                exams[i] = (s_i, d_i, c_i + 1)

        return False

    schedule = [0] * n
    if backtrack(1, schedule):
        return schedule
    else:
        return [-1]

